<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { supabase } from '../lib/supabase'
import type { Attribute, Character, Equipment, JournalEntry } from '../lib/types'

const route = useRoute(); const router = useRouter()
const character = ref<Character | null>(null); const attributes = ref<Attribute[]>([]); const equipment = ref<Equipment[]>([]); const journal = ref<JournalEntry[]>([])
const loading = ref(true); const saving = ref(false); const error = ref(''); const tab = ref(String(route.query.tab || 'overview')); const notFound = ref(false)
const editingAttribute = ref<string | null>(null); const attributeDraft = reactive({ name: '', value: '' }); const attributeError = ref('')
const equipmentModal = ref(false); const equipmentEditing = ref<Equipment | null>(null); const equipmentError = ref(''); const equipmentDraft = reactive({ item_name: '', item_type: '', quantity: '1', description: '' })
const journalModal = ref(false); const journalEditing = ref<JournalEntry | null>(null); const journalError = ref(''); const journalDraft = reactive({ session_date: '', title: '', campaign_name: '', attendees: '', events: '', rewards: '', notes: '' }); const deleting = ref<{ type: 'equipment' | 'journal'; item: Equipment | JournalEntry } | null>(null)

async function load() { loading.value = true; error.value = ''; const id = String(route.params.id); const [{ data: hero, error: heroError }, { data: stats }, { data: items }, { data: entries }] = await Promise.all([supabase.from('characters').select('*').eq('id', id).maybeSingle(), supabase.from('character_attributes').select('*').eq('character_id', id).order('position'), supabase.from('equipment').select('*').eq('character_id', id).order('item_name'), supabase.from('journal_entries').select('*').eq('character_id', id).order('session_date', { ascending: false })]); if (heroError || !hero) { notFound.value = true } else { character.value = hero; attributes.value = stats || []; equipment.value = items || []; journal.value = entries || [] }; loading.value = false }
function setTab(value: string) { tab.value = value; void router.replace({ query: { tab: value } }) }
function startAttribute(attribute: Attribute) { editingAttribute.value = attribute.id || null; attributeDraft.name = attribute.name; attributeDraft.value = attribute.value; attributeError.value = '' }
function cancelAttribute() { editingAttribute.value = null; attributeError.value = '' }
async function saveAttribute(attribute: Attribute) { if (!attributeDraft.name.trim() || !attributeDraft.value.trim()) { attributeError.value = 'Name and value are required.'; return }; if (attributeDraft.name.length > 50 || attributeDraft.value.length > 100) { attributeError.value = 'Name must be 50 characters or fewer and value must be 100 characters or fewer.'; return }; saving.value = true; const { data, error: updateError } = await supabase.from('character_attributes').update({ name: attributeDraft.name.trim(), value: attributeDraft.value.trim() }).eq('id', attribute.id).select().maybeSingle(); saving.value = false; if (updateError || !data) { attributeError.value = 'That attribute could not be saved.'; return }; Object.assign(attribute, data); cancelAttribute() }
async function addAttribute() { if (!attributeDraft.name.trim() || !attributeDraft.value.trim()) { attributeError.value = 'Name and value are required.'; return }; if (attributeDraft.name.length > 50 || attributeDraft.value.length > 100) { attributeError.value = 'Name must be 50 characters or fewer and value must be 100 characters or fewer.'; return }; saving.value = true; const { data, error: insertError } = await supabase.from('character_attributes').insert({ character_id: character.value?.id, name: attributeDraft.name.trim(), value: attributeDraft.value.trim(), position: attributes.value.length }).select().maybeSingle(); saving.value = false; if (insertError || !data) { attributeError.value = insertError?.message.includes('ATTRIBUTE_LIMIT_REACHED:') ? insertError.message.split(':').slice(1).join(':').trim() : 'That attribute could not be added.'; return }; attributes.value.push(data); attributeDraft.name = ''; attributeDraft.value = '' }
async function removeAttribute(attribute: Attribute) { if (!window.confirm(`Remove ${attribute.name}?`)) return; const { error: deleteError } = await supabase.from('character_attributes').delete().eq('id', attribute.id); if (deleteError) attributeError.value = 'That attribute could not be removed.'; else attributes.value = attributes.value.filter(item => item.id !== attribute.id) }
function resetEquipment(item?: Equipment) { equipmentEditing.value = item || null; equipmentDraft.item_name = item?.item_name || ''; equipmentDraft.item_type = item?.item_type || ''; equipmentDraft.quantity = String(item?.quantity ?? 1); equipmentDraft.description = item?.description || ''; equipmentError.value = ''; equipmentModal.value = true }
async function saveEquipment() { equipmentError.value = ''; if (!equipmentDraft.item_name.trim() || equipmentDraft.item_name.length > 100) equipmentError.value = 'Item name is required and must be 100 characters or fewer.'; else if (equipmentDraft.item_type.length > 50) equipmentError.value = 'Item type must be 50 characters or fewer.'; else if (!/^\d+$/.test(equipmentDraft.quantity) || Number(equipmentDraft.quantity) < 0) equipmentError.value = 'Quantity must be a whole number of 0 or more.'; else if (equipmentDraft.description.length > 1000) equipmentError.value = 'Description must be 1,000 characters or fewer.'; if (equipmentError.value) return; saving.value = true; const payload = { item_name: equipmentDraft.item_name.trim(), item_type: equipmentDraft.item_type || null, quantity: Number(equipmentDraft.quantity), description: equipmentDraft.description || null }; const result = equipmentEditing.value ? await supabase.from('equipment').update(payload).eq('id', equipmentEditing.value.id).select().maybeSingle() : await supabase.from('equipment').insert({ ...payload, character_id: character.value?.id }).select().maybeSingle(); saving.value = false; if (result.error || !result.data) { equipmentError.value = 'The equipment could not be saved.'; return }; if (equipmentEditing.value) Object.assign(equipmentEditing.value, result.data); else equipment.value.push(result.data); equipment.value.sort((a, b) => a.item_name.localeCompare(b.item_name)); equipmentModal.value = false }
async function saveJournal() { journalError.value = ''; if (!/^\d{4}-\d{2}-\d{2}$/.test(journalDraft.session_date) || Number.isNaN(new Date(`${journalDraft.session_date}T00:00:00`).getTime())) journalError.value = 'Enter a real calendar date.'; else if (!journalDraft.title.trim() || journalDraft.title.length > 150) journalError.value = 'Title is required and must be 150 characters or fewer.'; else if (journalDraft.campaign_name.length > 100 || journalDraft.attendees.length > 500 || journalDraft.events.length > 5000 || journalDraft.rewards.length > 2000 || journalDraft.notes.length > 5000) journalError.value = 'One or more journal fields exceed their length limit.'; if (journalError.value) return; saving.value = true; const payload = { session_date: journalDraft.session_date, title: journalDraft.title.trim(), campaign_name: journalDraft.campaign_name || null, attendees: journalDraft.attendees || null, events: journalDraft.events || null, rewards: journalDraft.rewards || null, notes: journalDraft.notes || null }; const result = journalEditing.value ? await supabase.from('journal_entries').update(payload).eq('id', journalEditing.value.id).select().maybeSingle() : await supabase.from('journal_entries').insert({ ...payload, character_id: character.value?.id }).select().maybeSingle(); saving.value = false; if (result.error || !result.data) { journalError.value = 'The journal entry could not be saved.'; return }; if (journalEditing.value) Object.assign(journalEditing.value, result.data); else journal.value.push(result.data); journal.value.sort((a, b) => b.session_date.localeCompare(a.session_date)); journalModal.value = false }
function resetJournal(entry?: JournalEntry) { journalEditing.value = entry || null; journalDraft.session_date = entry?.session_date || new Date().toISOString().slice(0, 10); journalDraft.title = entry?.title || ''; journalDraft.campaign_name = entry?.campaign_name || ''; journalDraft.attendees = entry?.attendees || ''; journalDraft.events = entry?.events || ''; journalDraft.rewards = entry?.rewards || ''; journalDraft.notes = entry?.notes || ''; journalError.value = ''; journalModal.value = true }
async function confirmDelete() { if (!deleting.value) return; const table = deleting.value.type === 'equipment' ? 'equipment' : 'journal_entries'; const { error: deleteError } = await supabase.from(table).delete().eq('id', deleting.value.item.id); if (deleteError) error.value = 'That record could not be deleted.'; else if (deleting.value.type === 'equipment') equipment.value = equipment.value.filter(item => item.id !== deleting.value?.item.id); else journal.value = journal.value.filter(item => item.id !== deleting.value?.item.id); deleting.value = null }
watch(() => route.query.tab, value => { tab.value = String(value || 'overview') }); onMounted(() => { void load() })
</script>
<template><section class="page"><div v-if="loading" class="empty"><p class="muted">Loading character…</p></div><div v-else-if="notFound" class="empty"><div class="empty-glyph">✦</div><h3>Character not found</h3><p class="muted">This character may have been removed or belongs to another chronicle.</p><button class="primary" @click="router.push('/characters')">Back to characters</button></div><div v-else-if="character"><button class="back-link" @click="router.push('/characters')">← Back to characters</button><div class="profile-head"><div class="avatar large">{{ character.name.charAt(0) }}</div><div><div class="eyebrow">Level {{ character.level ?? 0 }} · {{ character.role || 'Adventurer' }}</div><h2>{{ character.name }}</h2><p class="species">{{ character.species || 'Unknown' }} · {{ character.health ?? 0 }}/{{ character.max_health ?? 0 }} vitality</p></div><button class="outline" @click="router.push(`/characters/${character.id}/edit`)">Edit character</button></div><div class="tabs"><button :class="{ active: tab === 'overview' }" @click="setTab('overview')">Overview</button><button :class="{ active: tab === 'equipment' }" @click="setTab('equipment')">Equipment <span>{{ equipment.length }}</span></button><button :class="{ active: tab === 'journal' }" @click="setTab('journal')">Journal <span>{{ journal.length }}</span></button></div><div v-if="tab === 'overview'" class="detail-grid"><div class="detail-card stats-card"><div class="eyebrow">Core stats</div><div class="stat-line"><span>Level</span><strong>{{ character.level ?? 0 }}</strong></div><div class="stat-line"><span>Health</span><strong>{{ character.health ?? 0 }} / {{ character.max_health ?? 0 }}</strong></div><div class="stat-line"><span>Experience</span><strong>{{ character.experience ?? 0 }} XP</strong></div></div><div class="detail-card"><div class="eyebrow">Powers & abilities</div><p>{{ character.abilities || 'No abilities recorded yet.' }}</p></div><div class="detail-card"><div class="eyebrow">Backstory</div><p>{{ character.biography || 'This story is still being written.' }}</p></div><div class="detail-card"><div class="eyebrow">Custom attributes</div><div v-for="attribute in attributes" :key="attribute.id" class="inline-record"><template v-if="editingAttribute !== attribute.id"><span><strong>{{ attribute.name }}</strong> {{ attribute.value }}</span><span class="record-actions"><button class="text-link" @click="startAttribute(attribute)">Edit</button><button class="danger-text" @click="removeAttribute(attribute)">Remove</button></span></template><template v-else><input v-model="attributeDraft.name" maxlength="50" /><input v-model="attributeDraft.value" maxlength="100" /><button class="text-link" :disabled="saving" @click="saveAttribute(attribute)">Save</button><button class="danger-text" @click="cancelAttribute">Cancel</button></template></div><p v-if="!attributes.length" class="muted">No attributes recorded yet.</p><div class="inline-add"><input v-model="attributeDraft.name" maxlength="50" placeholder="Name" /><input v-model="attributeDraft.value" maxlength="100" placeholder="Value" /><button class="small-button" :disabled="saving" @click="addAttribute">＋ Add</button></div><p v-if="attributeError" class="form-error">{{ attributeError }}</p></div></div><div v-else-if="tab === 'equipment'" class="wide-detail"><div class="section-heading"><div><div class="eyebrow">What they carry</div><h3>Equipment</h3></div><button class="primary" @click="resetEquipment()">＋ Add item</button></div><p v-if="!equipment.length" class="muted">No equipment recorded yet.</p><div v-for="item in equipment" :key="item.id" class="item-row"><div class="item-icon">✦</div><div><strong>{{ item.item_name }}</strong><small>{{ item.item_type || 'Item' }} · {{ item.description || 'No description.' }}</small></div><span class="quantity">×{{ item.quantity }}</span><button class="text-link" @click="resetEquipment(item)">Edit</button><button class="danger-text" @click="deleting = { type: 'equipment', item }">Remove</button></div></div><div v-else class="wide-detail"><div class="section-heading"><div><div class="eyebrow">The story so far</div><h3>Session journal</h3></div><button class="primary" @click="resetJournal()">＋ New entry</button></div><p v-if="!journal.length" class="muted">No sessions recorded yet.</p><article v-for="entry in journal" :key="entry.id" class="journal-entry"><div class="journal-date"><strong>{{ entry.session_date.slice(8) }}</strong><span>{{ entry.session_date.slice(0,7) }}</span></div><div><div class="eyebrow">{{ entry.campaign_name || 'Unnamed campaign' }}</div><h3>{{ entry.title }}</h3><p>{{ entry.events || entry.notes || 'No events recorded.' }}</p><div class="journal-meta"><span>Players: {{ entry.attendees || 'Not recorded' }}</span><span>Rewards: {{ entry.rewards || 'None recorded' }}</span><span class="record-actions"><button class="text-link" @click="resetJournal(entry)">Edit</button><button class="danger-text" @click="deleting = { type: 'journal', item: entry }">Delete</button></span></div></div></article></div></div><p v-if="error" class="form-error">{{ error }}</p><div v-if="equipmentModal" class="modal-backdrop" @click.self="equipmentModal = false"><form class="modal modal-form" @submit.prevent="saveEquipment"><button type="button" class="modal-close" @click="equipmentModal = false">×</button><div class="eyebrow">{{ equipmentEditing ? 'Refine your kit' : 'Add to their kit' }}</div><h2>{{ equipmentEditing ? 'Edit equipment' : 'New equipment' }}</h2><label>Item name *<input v-model="equipmentDraft.item_name" maxlength="100" /></label><label>Item type<input v-model="equipmentDraft.item_type" maxlength="50" /></label><label>Quantity<input v-model="equipmentDraft.quantity" inputmode="numeric" /></label><label>Description<textarea v-model="equipmentDraft.description" maxlength="1000" rows="3"></textarea></label><p v-if="equipmentError" class="form-error">{{ equipmentError }}</p><button class="primary full" :disabled="saving">{{ saving ? 'Saving…' : 'Save equipment' }}</button></form></div><div v-if="journalModal" class="modal-backdrop" @click.self="journalModal = false"><form class="modal modal-form" @submit.prevent="saveJournal"><button type="button" class="modal-close" @click="journalModal = false">×</button><div class="eyebrow">{{ journalEditing ? 'Revise a memory' : 'Record a memory' }}</div><h2>{{ journalEditing ? 'Edit journal entry' : 'New journal entry' }}</h2><label>Session date *<input v-model="journalDraft.session_date" type="date" /></label><label>Title *<input v-model="journalDraft.title" maxlength="150" /></label><label>Campaign name<input v-model="journalDraft.campaign_name" maxlength="100" /></label><label>Players present<input v-model="journalDraft.attendees" maxlength="500" /></label><label>Important events<textarea v-model="journalDraft.events" maxlength="5000" rows="3"></textarea></label><label>Rewards<textarea v-model="journalDraft.rewards" maxlength="2000" rows="2"></textarea></label><label>Notes<textarea v-model="journalDraft.notes" maxlength="5000" rows="3"></textarea></label><p v-if="journalError" class="form-error">{{ journalError }}</p><button class="primary full" :disabled="saving">{{ saving ? 'Saving…' : 'Save journal entry' }}</button></form></div><div v-if="deleting" class="modal-backdrop" @click.self="deleting = null"><div class="modal"><div class="danger-icon">!</div><div class="eyebrow">A permanent choice</div><h2>Delete this {{ deleting.type === 'journal' ? 'entry' : 'item' }}?</h2><p class="muted">This action cannot be undone.</p><div class="modal-actions"><button class="outline" @click="deleting = null">Keep it</button><button class="danger full" @click="confirmDelete">Delete</button></div></div></div></section></template>
